}
#[test]
fn phase162_outbound_write_epoch_handed_frame() {
    run(Case::Epoch);
}
#[test]
fn phase162_outbound_write_disconnect() {
    run(Case::Disconnect);
}
#[test]
fn phase162_outbound_write_complete_control() {
    run(Case::Complete);
}

