        sync.network.consensus_params(),
        ScriptVerifyFlags::P2SH,
        102,
    );
    for (height, block) in recipe.blocks.iter().enumerate() {
        runtime
            .store()
            .save_block(block, PersistMode::Sync)
            .expect("actual body");
