        .store()
        .set_validation_history_fault(HistoryPublicationFault::SnapshotBeforeCommitFailure);
    // Act
    assert!(
        settle(&runtime).is_err(),
        "existing empty-coins refusal remains unchanged"
    );
    // Assert
    assert_eq!(runtime.store().snapshot_attempts(), [1, 1, 0, 0]);
