            .store()
            .load_header_entries()
            .expect("no repair")
            .is_none()
    );
    drop(handle);
    drop(reopened);
    std::fs::remove_dir_all(dir).expect("cleanup");
}

#[test]
fn phase162_header_checkpoint_reopen() {
    let params = SyncNetwork::Regtest.consensus_params();
    let request_limit = BasicFilterBranchLimit {
        branch: BranchWorkLimit {
            ancestry_steps: 16,
            identity_bytes: 4096,
        },
        metadata_units: 1024,
    };
    // Arrange
    let (dir, runtime, stale_hash) = stale_runtime();
    let handle = runtime.network_handle();
    let request = FilterRequest::Filters {
        filter_type: 0,
        start_height: 1,
        stop_hash: stale_hash,
    };

    // Act
    handle
        .flush_coins(
            FlushMode::Always,
            FlushPolicyTime::from_unix_seconds(20_002),
            u64::MAX,
        )
        .expect("replacement durable coins fence");
    let live = handle.peer_manager_snapshot().expect("live headers");
    let live_headers = live.header_store();
    let best = live_headers
        .maybe_best_proof_header()
        .expect("derived best proof");
    let stale = live_headers
        .maybe_proof_facts(stale_hash)
        .expect("derived stale proof");
    let exact_age = open_bitcoin_core::consensus::chain_proof::proof_equivalent_time(
        best.cumulative,
        stale.cumulative,
        best.block_proof,
        params.pow_target_spacing_seconds,
    )
    .expect("exact signed proof age");
    let timestamp_age = i64::from(best.timestamp) - i64::from(stale.timestamp);
    let live_capture = handle
        .capture_basic_filter_branch(2, request, params, request_limit)
        .expect("live capture");

    assert!(matches!(
        live_capture,
        BasicFilterBranchOutcome::Authorized(_)
    ));
    assert!(timestamp_age < 2_592_000 && exact_age < 2_592_000);

    let maybe_saved = runtime
        .store()
        .load_header_store()
        .expect("saved header snapshot");

    assert!(
        maybe_saved
            .expect("normal snapshot")
            .entry(&stale_hash)
            .is_some()
    );
    drop(handle);
    drop(runtime);
    let reopened = DurableSyncRuntime::open(
        crate::FjallNodeStore::open(&dir).expect("all-handle store reopen"),
        crate::SyncRuntimeConfig {
            network: SyncNetwork::Regtest,
            ..Default::default()
        },
    )
    .expect("cold runtime");
    let handle = reopened.network_handle();
    handle
        .configure_basic_peer_serving(true)
        .expect("explicit cold capability");
    handle
        .connect_outbound_peer(2, 10_000)
        .expect("cold advertising peer");
    let cold = handle.peer_manager_snapshot().expect("cold headers");
    let cold_headers = cold.header_store();
    let cold_capture = handle
        .capture_basic_filter_branch(2, request, params, request_limit)
        .expect("cold capture");
    let provenance = reopened
        .store()
        .validation_provenance(stale_hash)
        .expect("cold provenance");

    // Assert: ordinary settlement retains exact admitted stale proof and provenance.
    assert_eq!(provenance, ValidationProvenance::ScriptsValid);
    assert!(cold_headers.entry(&stale_hash).is_some());
    assert_eq!(cold_headers.maybe_proof_facts(stale_hash), Some(stale));
    assert_eq!(cold_headers.maybe_best_proof_header(), Some(best));
    assert_eq!(timestamp_age, 100);
    assert_eq!(exact_age, 600);
    assert!(matches!(
        cold_capture,
        BasicFilterBranchOutcome::Authorized(_)
    ));
    drop(handle);
    drop(reopened);
    std::fs::remove_dir_all(dir).expect("all handles dropped before cleanup");
}

fn stale_runtime() -> (std::path::PathBuf, DurableSyncRuntime, BlockHash) {
    stale_runtime_configured(false)
}

fn stale_runtime_configured(indexed: bool) -> (std::path::PathBuf, DurableSyncRuntime, BlockHash) {
    // Arrange: ordinary mined coinbase-only history, with no maturity override.
    let params = SyncNetwork::Regtest.consensus_params();
    assert_eq!(params.coinbase_maturity, 100);
    let (dir, runtime) = runtime("phase162-stale-normal");
    let handle = runtime.network_handle();
    handle.disconnect_peer(1).expect("replace initial session");
    handle
        .configure_basic_peer_serving(true)
        .expect("explicit BASIC capability");
    handle
        .connect_outbound_peer(2, 10_000)
        .expect("advertising peer");
    let genesis = block(BlockHash::default(), 0, 0x51);
    let old = block(block_hash(&genesis.header), 1, 0x51);
    let stale_hash = block_hash(&old.header);
    for accepted in [&genesis, &old] {
        runtime
            .store()
            .save_block(accepted, crate::PersistMode::Sync)
            .expect("ordinary body");
        handle
            .connect_local_block(accepted, ScriptVerifyFlags::P2SH, params)
            .expect("genuine accept");
    }
    handle
        .flush_coins(
            FlushMode::Always,
            FlushPolicyTime::from_unix_seconds(20_000),
            u64::MAX,
        )
        .expect("old durable coins fence");
    drop(handle);
    let runtime = if indexed {
        drop(runtime);
        DurableSyncRuntime::open_configured(
            crate::FjallNodeStore::open(&dir).expect("closed indexed reopen"),
            crate::SyncRuntimeConfig {
                network: SyncNetwork::Regtest,
                ..Default::default()
            },
            crate::chainstate::BasicFilterStartupMode::Enabled,
        )
        .expect("genuine accepted BASIC owner")
    } else {
        runtime
    };
    let handle = runtime.network_handle();
    if indexed {
        handle.configure_basic_peer_serving(true).expect("BASIC");
        handle.connect_outbound_peer(2, 10_000).expect("new peer");
    }
    assert_eq!(
        runtime
            .store()
            .validation_provenance(stale_hash)
            .expect("accepted provenance"),
        ValidationProvenance::ScriptsValid
    );
    assert!(
        handle
            .peer_manager_snapshot()
            .expect("live accepted headers")
            .header_store()
            .entry(&stale_hash)
            .is_some()
    );
    let alternate = block(block_hash(&genesis.header), 1, 0x52);
    let extension = block(block_hash(&alternate.header), 2, 0x52);
    let replacement = vec![
        AnchoredBlock {
            block: alternate,
            chain_work: 3,
        },
        AnchoredBlock {
            block: extension,
            chain_work: 4,
        },
    ];
    for accepted in &replacement {
        runtime
            .store()
            .save_block(&accepted.block, crate::PersistMode::Sync)
            .expect("competing body");
    }

    // Genuine managed reorg leaves old h1 admitted but stale.
    let transition = handle
        .reorg_to_branch(
            &[old],
            &replacement,
            ReorgLifecycleContext::new(PolicyTime::from_unix_seconds(20_001)),
            ScriptVerifyFlags::P2SH,
            params,
        )
        .expect("genuine reorg");
    assert_eq!(transition.disconnected.len(), 1);
    assert_eq!(transition.connected.len(), 2);
    drop(handle);
    (dir, runtime, stale_hash)
}
